const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const home_page_header = require('home_page_header')
const action_buttons = require('action_buttons')
const transaction_list = require('transaction_list')
const total_wealth = require('total_wealth')
const lightning_buttons = require('lightning_buttons')
const wallet_button = require('wallet_button')
const light_page_header = require('light_page_header')
const light_tx_list = require('light_tx_list')
const contacts_list = require('contacts_list')
const net = require('net_helper')
const ws_client = require('ws_client')

module.exports = home_contents

async function home_contents(opts = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = { style: inject, data: ondata }

  let sendToActionButtons = null
  let currentBtc = 0
  let currentLn = 0
  let nodeAlias = ''
  const wait = {}

  const el = document.createElement('div')
  el.id = "home_contents"
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="home-contents-container"></div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const container = shadow.querySelector('.home-contents-container')

  const subs = await sdb.watch(onbatch)

  // -------------------- net_helper setup --------------------
  const { io, _ } = net(id)
  io.on.backend = io_backend()
  io.accept(make_ws_backend_invite('backend')) // Mount ws_client as the real backend tunnel

  // Prepare io.on handlers for each child (noops — home_contents is the root sender)
  function noop() { }
  io.on.home_page_header = noop
  io.on.total_wealth = noop
  io.on.light_page_header = noop
  io.on.light_tx_list = noop
  io.on.transaction_list = noop
  io.on.contacts_list = noop
  io.on.wallet_button = on_wallet_button

  // -------------------- Create components and wire invites --------------------
  const headerOpts = { wallet: 'btc', amount: '0.9616' }
  const home_page_header_component = await home_page_header(subs[0], headerOpts)
  io.accept(home_page_header_component.invite)

  const action_buttons_component = await action_buttons(subs[1], home_protocol)
  const transaction_list_component = await transaction_list(subs[2])
  io.accept(transaction_list_component.invite)

  const total_wealth_component = await total_wealth(subs[3])
  io.accept(total_wealth_component.invite)

  const lightning_buttons_component = await lightning_buttons(subs[4], null)
  const wallet_button_component = await wallet_button(subs[5], null)
  io.accept(wallet_button_component.invite)

  const light_page_header_component = await light_page_header(subs[6])
  io.accept(light_page_header_component.invite)

  const light_tx_list_component = await light_tx_list(subs[7])
  io.accept(light_tx_list_component.invite)

  const contacts_list_component = await contacts_list(subs[8])
  io.accept(contacts_list_component.invite)

  // Expose live-wired contacts_list_component so menu can use it in the Contacts tab
  el.contacts_list_component = contacts_list_component

  // default view: BTC wallet components
  container.append(
    home_page_header_component,
    wallet_button_component,
    action_buttons_component,
    transaction_list_component,
    total_wealth_component
  )

  function fetchNodeInfo() {
    const head = _.backend('lightning-getinfo', { cause: [] }, { nodeId: 'node4' })
    wait[head[2]] = function (m) {
      const info = m.data?.data
      if (info?.alias) nodeAlias = info.alias
    }
  }

  function fetchBalances() {
    const btcHead = _.backend('get_btc_balance', { cause: [] })
    wait[btcHead[2]] = function (m) {
      currentBtc = m.data?.data?.btc || 0
      updateUI()
    }
    const lnHead = _.backend('get_ln_balance', { cause: [] }, { userId: 'node4' })
    wait[lnHead[2]] = function (m) {
      const d = m.data?.data
      if (d) currentLn = d.btc || 0
      updateUI()
    }
  }

  function fetchBtcTransactions() {
    const reqHead = _.backend('get_active_requests', { cause: [] }, {})
    wait[reqHead[2]] = function (reqMsg) {
      const requests = reqMsg.data?.data || []
      const head = _.backend('list_btc_transactions', { cause: [] }, { count: 20, skip: 0 })
      wait[head[2]] = function (m) {
        const txs = m.data?.data
        if (!Array.isArray(txs)) return
        const formatted = txs.map(function (tx) {
          const date = new Date(tx.time * 1000)
          const dateString = date.toISOString().split('T')[0]
          const ttime = date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true })
          const sign = tx.category === 'send' ? '-' : '+'
          const tamount = `${sign}${Math.abs(tx.amount).toFixed(8)}`
          const tid = nodeAlias || tx.txid || tx.address || 'Unknown'

          // Match address with requests to find custom description/tag
          const matchedReq = requests.find(r => r.id === tx.address && r.type === 'BTC')
          const customDesc = matchedReq ? matchedReq.description : ''

          return {
            tid,
            ttime,
            tamount,
            dateString,
            avatar: '',
            txid: tx.txid || '',
            address: tx.address || '',
            category: tx.category || '',
            label: customDesc || tx.description || tx.tag || tx.label || tx.comment || ''
          }
        })
        _.transaction_list('update', { cause: [] }, formatted)
        // Also relay to action_buttons so send_btc can populate templates from real tx history
        if (sendToActionButtons) {
          sendToActionButtons({ type: 'btc_transactions_updated', data: { txs: formatted } })
        }
      }
    }
  }

  function fetchLnTransactions() {
    const head = _.backend('get_transaction_history', { cause: [] }, { userId: 'node4', limit: 200 })
    wait[head[2]] = function (m) {
      const history = m.data?.data
      if (!Array.isArray(history)) return
      const lnTxs = history.filter(function (tx) { return tx.type === 'LN' })
      const formatted = lnTxs.map(function (tx) {
        const date = new Date(tx.timestamp * 1000)
        const dateString = date.toISOString().split('T')[0]
        const ttime = date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true })
        const sign = tx.direction === 'IN' ? '+' : '-'
        const amountSats = Math.round(tx.amount_msat / 1000)
        const tamount = `${sign}${amountSats} sats`
        const tid = tx.note || tx.label || tx.description || tx.id || 'Unknown'
        return { tid, ttime, tamount, dateString, avatar: '', payment_hash: tx.payment_hash || tx.id || '', direction: tx.direction, status: tx.status }
      })
      if (light_tx_list_component && light_tx_list_component._update) {
        light_tx_list_component._update(formatted)
      }
    }
  }

  function fetchContacts() {
    const head = _.backend('contact_list', { cause: [] }, {})
    wait[head[2]] = function (m) {
      // Real backend response
      const payload = m.data?.data
      if (!payload) return
      const contacts = Array.isArray(payload) ? payload : (payload.data || [])
      if (!Array.isArray(contacts)) return
      const formatted = contacts.map(function (c) {
        // Real fields from contact_list: { id, name, address, type, note }
        const seed = encodeURIComponent(c.address || c.name || c.id || 'contact')
        return {
          id: c.id || '',
          name: c.name || 'Unknown',
          avatar: `https://api.dicebear.com/7.x/identicon/svg?seed=${seed}`,
          message: c.note || c.type ? `${c.type || ''}${c.note ? ' — ' + c.note : ''}` : '',
          time: '',
          unread: 0,
          online: false,
          address: c.address || '',
          type: c.type || ''
        }
      })
      _.contacts_list('update', { cause: [] }, formatted)
    }
  }

  function updateUI() {
    const total = Number(currentBtc) + Number(currentLn)
    _.total_wealth('update', { cause: [] }, { total, lightning: Number(currentLn), bitcoin: Number(currentBtc) })
    _.home_page_header('update', { cause: [] }, { wallet: 'btc', amount: currentBtc })
    _.light_page_header('update', { cause: [] }, { wallet: 'lightning', amount: currentLn })
    _.wallet_button('update', { cause: [] }, { btc: Number(currentBtc), lightning: Number(currentLn) })
    if (sendToActionButtons) {
      sendToActionButtons({ type: 'btc_balance_updated', data: { balance: Number(currentBtc) } })
    }
  }

  function io_backend() {
    const on = {
      payment_received: on__update,
      request_update: on__update,
    }
    return protocol
    function protocol(m) {
      // Real backend sends type like 'get_btc_balance:response' or push types
      const basetype = m.type ? m.type.replace(/:response$/, '') : ''
      if (on[basetype]) return on[basetype](m)
      if (on[m.type]) return on[m.type](m)
      on__response(m)
    }
    function on__response(m) {
      // Real backend echoes head: ['backend', by, mid] — match on mid (head[2])
      const mid = m.head?.[2]
      if (mid === undefined) return
      const handler = wait[mid]
      if (!handler) return
      delete wait[mid]
      handler(m)
    }
    function on__update() {
      fetchBalances()
      fetchBtcTransactions()
      fetchLnTransactions()
    }
  }

  // Initial fetch
  fetchNodeInfo()
  fetchBalances()
  fetchBtcTransactions()
  fetchLnTransactions()
  fetchContacts()

  // Periodic refresh (10s)
  setInterval(() => {
    fetchBalances()
    fetchBtcTransactions()
    fetchLnTransactions()
    fetchContacts()
  }, 10000)

  return el

  // -------------------- Protocol handlers --------------------
  function on_wallet_button(m) {
    if (m.type !== 'switch') return
    const wallet = m.data?.data
    if (wallet === 'btc') {
      _.home_page_header('update', { cause: [] }, { wallet: 'btc', amount: currentBtc || '0.00' })
      container.replaceChildren(
        home_page_header_component,
        wallet_button_component,
        action_buttons_component,
        transaction_list_component,
        total_wealth_component
      )
    } else if (wallet === 'lightning') {
      _.light_page_header('update', { cause: [] }, { wallet: 'lightning', amount: currentLn || '0.00' })
      container.replaceChildren(
        light_page_header_component,
        wallet_button_component,
        lightning_buttons_component,
        light_tx_list_component,
        total_wealth_component
      )
    }
  }

  function home_protocol(sendToChild) {
    sendToActionButtons = sendToChild
    sendToChild({ type: 'btc_balance_updated', data: { balance: Number(currentBtc) } })
    return async function (messageFromChild) {
      if (!messageFromChild) return

      // ---- Auto-generate BTC Receive Address (with default or no description) ----
      if (messageFromChild.type === 'generate_btc_address') {
        const description = messageFromChild.data?.description || 'Payment'

        //  call bitcoin newaddress to get a fresh address
        const head = _.backend('bitcoin-newaddress', { cause: [] }, {})
        wait[head[2]] = function (m) {
          const addr = m.data?.data
          if (!addr) {
            // relay failure back so receive_btc can show error state
            sendToChild({ type: 'btc_address_generated', data: { address: '' } })
            return
          }

          //  persist the request via save_request with default description
          _.backend('save_request', { cause: [] }, {
            id: addr,
            type: 'BTC',
            amount: '0',
            description: description
          })

          // send address back down to action_buttons to receive_btc
          sendToChild({ type: 'btc_address_generated', data: { address: addr } })
        }
      }

      //  Update description on existing address 
      if (messageFromChild.type === 'update_btc_description') {
        const address = messageFromChild.data?.address || ''
        const description = messageFromChild.data?.description || ''
        if (!address) return

        // Overwrite the request record with the same address + new description
        const head = _.backend('save_request', { cause: [] }, {
          id: address,
          type: 'BTC',
          amount: '0',
          description: description
        })
        wait[head[2]] = function (m) {
          const ok = !m.data?.error
          sendToChild({ type: 'btc_description_updated', data: { success: ok } })
        }
      }

      //  Send BTC payment onchain
      if (messageFromChild.type === 'send_btc_payment') {
        const { address, amount } = messageFromChild.data || {}
        const data = {
          recipient_address: address,
          amount_btc: parseFloat(amount),
          fee_rate_sats_per_vb: 10 // default fee rate
        }
        const head = _.backend('send_btc_onchain', { cause: [] }, data)
        wait[head[2]] = function (m) {
          const ok = m.data?.status === 'success'
          const error = m.data?.error || ''
          sendToChild({
            type: 'btc_payment_sent',
            data: { success: ok, error, txid: m.data?.data?.tx_id || '' }
          })
          if (ok) {
            // refresh balances and transactions
            fetchBalances()
            fetchBtcTransactions()
          }
        }
      }
    }
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(p => drive.get(p).then(f => f.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) { style.textContent = data[0] }
  function ondata(data) { }
  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }

  // ---- ws_client to net_helper bridge ----
  function make_ws_backend_invite(name) {
    return Object.assign(invite_fn, { ids: { [name]: ws_client.id } })
    function invite_fn(rx) {
      ws_client.bind(function (M) {
        try { rx(M) } catch (e) { console.error('[home_contents] ws rx error:', e) }
      })
      // net_helper's add() calls tx() directly as a function 
      const tx_fn = function (M) { ws_client.tx(M) }
      tx_fn.id = ws_client.id
      return tx_fn
    }
  }
}

// ------------------ Fallback for STATE ------------------
function fallback_module() {
  return {
    api,
    _: {
      'home_page_header': { $: '' },
      'action_buttons': { $: '' },
      'transaction_list': { $: '' },
      'total_wealth': { $: '' },
      'lightning_buttons': { $: '' },
      'wallet_button': { $: '' },
      'light_page_header': { $: '' },
      'light_tx_list': { $: '' },
      'contacts_list': { $: '' },
      'net_helper': { $: '' },
      'ws_client': { $: '' }
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const home_page_header = {
      mapping: { style: 'style', data: 'data', icons: 'icons' },
      0: { wallet: 'btc', amount: '0.9616' }
    }
    const action_buttons = { mapping: { style: 'style', data: 'data' }, 0: { buttons: { wallet: 'btc' } } }
    const transaction_list = {
      mapping: { style: 'style', data: 'data' },
      0: {
        value: [
          { tid: 'Luis fedrick', ttime: '11:30 AM', tamount: '+0.02456', avatar: 'https://tse4.mm.bing.net/th/id/OIP.VIRWK2jj8b2cHBaymZC5AgHaHa?w=800&h=800&rs=1&pid=ImgDetMain&o=7&rm=3' },
          { tid: 'skdmf932ksdmf0234lsd', ttime: '02:15 PM', tamount: '+0.03271', avatar: '' },
          { tid: 'Mark Kevin', ttime: '03:45 PM', tamount: '-0.00421', avatar: 'https://tse4.mm.bing.net/th/id/OIP.VIRWK2jj8b2cHBaymZC5AgHaHa?w=800&h=800&rs=1&pid=ImgDetMain&o=7&rm=3' },
          { tid: 'yweuyiewe32eqw234lsd', ttime: '12:30 PM', tamount: '+0.00567', avatar: '' },
        ]
      }
    }
    const total_wealth = {
      mapping: { style: 'style', data: 'data', icons: 'icons' },
      0: { value: { total: 0.9862, usd: 1000, lightning: 0.02456, bitcoin: 0.96164 } }
    }
    const lightning_buttons = { mapping: { style: 'style', data: 'data' }, 0: { buttons: { wallet: 'lightning' } } }
    const wallet_button = { mapping: { style: 'style', data: 'data' }, 0: { buttons: { wallet: 'btc' } } }
    const light_page_header = {
      mapping: { style: 'style', data: 'data', icons: 'icons' },
      0: { wallet: 'lightning', amount: '0.0246' }
    }
    const light_tx_list = {
      mapping: { style: 'style', data: 'data' },
      0: {
        value: [
          { tid: 'Luis Fedrick', ttime: '09:15 AM', tamount: '-12300 sats', dateString: '', avatar: '' },
          { tid: 'Mark Kevin', ttime: '12:30 PM', tamount: '+56700 sats', dateString: '', avatar: '' },
          { tid: 'Luis Fedrick', ttime: '04:20 PM', tamount: '-23400 sats', dateString: '', avatar: '' },
          { tid: 'Mark Kevin', ttime: '12:30 PM', tamount: '+56700 sats', dateString: '', avatar: '' },
        ]
      }
    }
    const net_helper = {
      mapping: { style: 'style', data: 'data' },
      0: {}
    }
    const ws_client = {
      mapping: { style: 'style', data: 'data' },
      0: {}
    }

    const contacts_list = {
      mapping: { style: 'style', data: 'data' },
      0: {
        value: []
      }
    }

    return {
      drive: {
        'style/': {
          'home_contents.css': {
            '$ref': 'home_contents.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {
        home_page_header,
        action_buttons,
        transaction_list,
        total_wealth,
        lightning_buttons,
        wallet_button,
        light_page_header,
        light_tx_list,
        contacts_list
      }
    }
  }
}